contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 id) public payable {
        require(id != bytes32(0), "id must be nonzero");
        require(c.hasRole(keccak256("PROPOSER_ROLE"), address(this)), "no proposer role");
        require(c.getTimestamp(id) == 0, "slot must be empty");

        c.schedule(address(this), 0, "", bytes32(0), id, c.getMinDelay());

        bool pendingBefore = c.isOperationPending(id);
        require(pendingBefore, "operation should be pending before cancel");

        c.cancel(id);

        assert(c.getTimestamp(id) == 0 && !c.isOperationPending(id));
    }

    receive() external payable {}
}

